import{_ as t,o,c as d,ag as r}from"./chunks/framework.D9kpkP22.js";const u=JSON.parse('{"title":"Setup All Plugins Together","description":"","frontmatter":{"title":"Setup All Plugins Together"},"headers":[],"relativePath":"guide/setup-all.md","filePath":"guide/setup-all.md"}'),c={name:"guide/setup-all.md"};function a(s,e,i,n,l,p){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="setup-all-plugins-together" tabindex="-1">Setup All Plugins Together <a class="header-anchor" href="#setup-all-plugins-together" aria-label="Permalink to &quot;Setup All Plugins Together&quot;">​</a></h1><p>Install the full <strong>FragMC stack</strong> on one <strong>Paper 26.2</strong> server in under 10 minutes. This page covers the current <code>2.0.10-alpha</code> <code>Java 25</code> stack in the order that matters.</p><div class="warning custom-block"><p class="custom-block-title">Deprecated</p><p><code>Telepipe</code> is <strong>deprecated</strong> and not part of this guide. Use <code>IcedSpear</code> map warping. See <code>Telepipe</code> page if you still need it.</p></div><h2 id="at-a-glance" tabindex="-1">At a Glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a Glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Plugins</th><th>Version</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Core</strong></td><td>IcedSpear</td><td><code>2.0.10-alpha</code></td><td>Map/Party/Friends/Leaderboards</td></tr><tr><td><strong>Addons</strong></td><td>Editor, Blocks, IcedScore, Weblink</td><td><code>2.0.10-alpha</code></td><td>Same <code>FragMC/Icedspear</code> repo</td></tr><tr><td><strong>Standalone</strong></td><td>Frost, CheckPoints, Redempt</td><td><code>2.0.10-alpha</code></td><td>Shop, checkpoints, redeem</td></tr><tr><td><strong>Bot</strong></td><td>Map-Submission-Bot</td><td><code>2.0.10-alpha</code></td><td><code>Node 20</code> <code>Docker</code> <code>ghcr.io/fragmc/map-submission-bot:latest</code></td></tr></tbody></table><p><strong>What you get:</strong> Maps, parties, leaderboards, shop with hotbar skins, checkpoints, redeem codes, in-game editor, and Discord ticket flow.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Requirements</p><p><strong>Required:</strong> Paper <code>26.2.build.123-stable</code>, Java <code>25</code> (Temurin), Maven <code>3.9+</code></p><p><strong>For maps:</strong> FastAsyncWorldEdit <code>2.11.1</code> + WorldEdit</p><p><strong>For economy:</strong> Vault + EssentialsX <code>2.20.1</code></p><p><strong>Optional but recommended:</strong> Geyser <code>2.2.0+</code> + Floodgate <code>2.2.0+</code> (Bedrock), FreeMinecraftModels <code>2.7.1+</code> (skins), Multiverse-Core (editor worlds). SQLite is bundled.</p></div><h2 id="_1-get-the-jars" tabindex="-1">1. Get the Jars <a class="header-anchor" href="#_1-get-the-jars" aria-label="Permalink to &quot;1. Get the Jars&quot;">​</a></h2><p>All plugins are published to <strong>GitHub Packages</strong> and <strong>Modrinth</strong> as <code>2.0.10-alpha</code>. Pick one:</p><div class="tip custom-block"><p class="custom-block-title">Download (Recommended)</p><p>Grab the ready-made jars from <strong>Releases</strong> <code>v2.0.10-alpha</code> on GitHub (<code>Frost</code>, <code>IcedSpear</code>, <code>CheckPoints</code>, <code>Redempt</code>) and <code>ghcr.io/fragmc/map-submission-bot:latest</code> for the bot. No build needed.</p></div><details><summary>Or build locally with JDK 25</summary><p>You need <code>Java 25</code> and <code>Maven 3.9+</code>. Run in order (some addons depend on the core):</p><ul><li>Core and editor: <code>IcedSpear</code> → <code>Editor</code> (install first so others can find it)</li><li>Then: <code>Blocks</code>, <code>IcedScore</code>, <code>Weblink</code>, <code>Frost</code>, <code>CheckPoints</code>, <code>Redempt</code></li></ul><p>Artifacts land in <code>target/</code> e.g. <code>IcedSpear/target/icedspear-2.0.10-alpha.jar</code>, <code>Addons/Editor/target/editor-addon-2.0.10-alpha.jar</code>, etc.</p></details><h2 id="_2-install-order" tabindex="-1">2. Install Order <a class="header-anchor" href="#_2-install-order" aria-label="Permalink to &quot;2. Install Order&quot;">​</a></h2><p>Drop the jars into <code>plugins/</code> in this order, then start the server once to generate configs:</p><table tabindex="0"><thead><tr><th>Order</th><th>Jar</th><th>Why this order</th></tr></thead><tbody><tr><td>1</td><td><code>FastAsyncWorldEdit-Bukkit</code> <code>2.11.1</code>, <code>Vault</code>, <code>EssentialsX</code> <code>2.20.1</code></td><td>Dependencies</td></tr><tr><td>2</td><td><code>IcedSpear-2.0.10-alpha.jar</code></td><td>Core</td></tr><tr><td>3</td><td><code>EditorAddon-2.0.10-alpha.jar</code></td><td>Requires core</td></tr><tr><td>4</td><td><code>BlocksAddon-2.0.10-alpha.jar</code></td><td>Requires Editor, auto-installs zone models</td></tr><tr><td>5</td><td><code>IcedScores-2.0.10-alpha.jar</code> + <code>weblink-addon-2.0.10-alpha.jar</code></td><td>Needs <code>IcedSpear</code> + <code>ImageFrame</code></td></tr><tr><td>6</td><td><code>Frost</code>, <code>CheckPoints</code>, <code>Redempt</code> <code>2.0.10-alpha</code></td><td>Standalone</td></tr><tr><td>7</td><td><code>Geyser-Spigot</code> + <code>Floodgate</code> + <code>FreeMinecraftModels</code></td><td>Optional: Bedrock + skins</td></tr></tbody></table><p>After first start you’ll see <code>plugins/Frost/config.yml</code>, <code>plugins/IcedSpear/config.yml</code>, <code>plugins/EditorAddon/dropbox/</code> etc.</p><h2 id="_3-configure" tabindex="-1">3. Configure <a class="header-anchor" href="#_3-configure" aria-label="Permalink to &quot;3. Configure&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Key Files</p><p>All paths are relative to your server <code>plugins/</code> folder. Edit with any text editor, then <code>/frost reload</code> or restart.</p></div><table tabindex="0"><thead><tr><th>Plugin</th><th>File</th><th>What to Set</th></tr></thead><tbody><tr><td><strong>IcedSpear</strong></td><td><code>IcedSpear/config.yml</code></td><td><code>map-data-url</code> points to your <code>icedspear.json</code></td></tr><tr><td><strong>Frost</strong></td><td><code>Frost/config.yml</code></td><td><code>warrior</code> hotbar is now <code>Spear/Mace/Wind Charge</code> in slots 1-3, slots 4-9 via <code>/inventory</code></td></tr><tr><td><strong>Redempt</strong></td><td><code>Redempt/config.yml</code></td><td><code>currency-symbol</code>, SQLite <code>promocodes.db</code></td></tr><tr><td><strong>Editor</strong></td><td><code>EditorAddon/config.yml</code></td><td>Add <code>dropbox-enc-key</code> to encrypt Dropbox tokens</td></tr><tr><td><strong>WebLink</strong></td><td><code>Weblink/config.yml</code></td><td><code>webhook-port</code> and <code>webhook-secret</code> (use an env var)</td></tr><tr><td><strong>MapBot</strong></td><td><code>Map-Submission-Bot/.env</code></td><td>All Discord/GitHub IDs (see <code>.env.example</code>)</td></tr></tbody></table><h2 id="_4-first-run-checklist" tabindex="-1">4. First Run Checklist <a class="header-anchor" href="#_4-first-run-checklist" aria-label="Permalink to &quot;4. First Run Checklist&quot;">​</a></h2><ol><li>Start <code>Paper 26.2</code> with <code>Java 25</code> - all plugins should enable green. If you have <code>Geyser</code>/<code>Floodgate</code>/<code>FMM</code>/<code>Multiverse-Core</code>, they’ll be detected automatically.</li><li>In-game as <code>OP</code>: try <code>/map create test</code> - first time it will ask you to <code>/map linkdropbox</code> your Dropbox. Link once, then create again.</li><li>Try <code>/editor preview</code> - it should switch you between <code>Creative</code> (you see zone blocks as glass) and <code>Adventure</code> (blocks disappear, only floating gold/emerald markers remain).</li><li>On Discord, check your <code>MapBot</code> channel - you should see the <code>Submit a map | Report a map</code> embed. Try a test submission.</li><li>Open <code>https://fragmc.github.io/maps/viewer.html?id=tutorial</code> - it should show the <code>Tutorial</code> map, and <code>?schematic=&lt;your dl.dropbox link&gt;</code> should load your schematic.</li></ol><h2 id="_5-not-included" tabindex="-1">5. Not Included <a class="header-anchor" href="#_5-not-included" aria-label="Permalink to &quot;5. Not Included&quot;">​</a></h2><ul><li><strong>Telepipe</strong> <code>telepipe/index.md:1</code> is <strong>deprecated</strong> - <code>Web-based teleportation</code> <code>json-url: &quot;https://example.com/teleports.json&quot;</code> <code>FRAMC-Docs/telepipe/index.md:35</code> still works on <code>Paper 26.2</code> <code>api-version: &#39;26.2&#39;</code> but use <code>IcedSpear</code> <code>MapManager</code> <code>public/private</code> warp instead. Marked deprecated in <code>nav</code> and page banner below.</li></ul>',23)])])}const g=t(c,[["render",a]]);export{u as __pageData,g as default};
